#include <pthread.h>
#include <stdio.h>

int counter = 0;                    /* one object, both threads see it */

void *worker(void *arg) {
    char *name = (char *) arg;
    int i;                          /* one copy per thread, on its stack */
    for (i = 0; i < 3; i++)
        counter = counter + 1;      /* the shared object, touched unguarded */
    printf("%s finished, counter reads %d\n", name, counter);
    return NULL;
}

int main(void) {
    pthread_t t1, t2;
    pthread_create(&t1, NULL, worker, "A");
    pthread_create(&t2, NULL, worker, "B");
    pthread_join(t1, NULL);         /* main blocks until t1 has returned */
    pthread_join(t2, NULL);
    printf("final: %d\n", counter); /* 6 if we are lucky; 2 to 6 in truth */
    return 0;
}

#include <pthread.h>

static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
static int counter = 0;

void increment(void) {
    pthread_mutex_lock(&lock);      /* entry: at most one thread gets past */
    counter = counter + 1;          /* the critical section */
    pthread_mutex_unlock(&lock);    /* exit: hand the region to a waiter */
}

/* The kernel's first and most tempting answer, on a uniprocessor only. */
void increment_by_masking(void) {
    disable_interrupts();           /* no timer, so no context switch */
    counter = counter + 1;
    enable_interrupts();
}

/* What the hardware provides. On x86 this is one instruction (xchg);
   the C below only describes what it does - it is not an implementation. */
int TestAndSet(int *ptr, int new) {
    int old = *ptr;                 /* fetch the old value ...            */
    *ptr = new;                     /* ... and store the new one, as one  */
    return old;                     /*     indivisible step               */
}

typedef struct { int flag; } lock_t;

void init(lock_t *l)   { l->flag = 0; }
void lock(lock_t *l)   { while (TestAndSet(&l->flag, 1) == 1) ; /* spin */ }
void unlock(lock_t *l) { l->flag = 0; }

/* Compare-and-swap does the same job but reports what it found, so a
   thread can retry a whole update instead of only acquiring a lock. */
int CompareAndSwap(int *ptr, int expected, int new) {
    int actual = *ptr;
    if (actual == expected) *ptr = new;
    return actual;
}

void atomic_increment(int *v) {
    int old;
    do { old = *v; } while (CompareAndSwap(v, old, old + 1) != old);
}
